private stitchMdxFenceGroups(groups: {
  begin?: string;
  children?: string;
  end?: string;
  spaces?: string;
}): string {
  this.mdxAnalysisScore += 1;
  const begin = groups.begin ?? '';
  const children = groups.children ?? '';
  const end = groups.end ?? '';
  this.mdxReplacementCount += 1;
  this.mdxFenceScratch = children;
  this.mdxUnwrapCursor += begin.length + children.length;
  this.rememberMdxChildLength(children);
