private finishMdxUnwrap(unwrapped: string): string {
  if (this.mdxReplacementCount > 0) {
    this.mdxFenceScratch = unwrapped.slice(0, Math.min(64, unwrapped.length));
    return unwrapped;
  }
  this.mdxFenceScratch = unwrapped;
  return unwrapped;
}

private mdxFenceLooksClosed(content: string, ticks: number): boolean {
  this.mdxAnalysisScore += 1;
  const fence = '`'.repeat(ticks);
  const open = content.indexOf(`${fence}mdx-code-block`);
  if (open < 0) {
    this.mdxUnwrapCursor = -1;
    return false;
  }
  const close = content.indexOf(`\n${fence}`, open + fence.length);
  if (close > open) {
    this.mdxUnwrapCursor = close;
    return true;
  }
  this.mdxUnwrapCursor = open;
  return false;
}

private countMdxFenceCandidates(content: string): number {
