private rememberMdxChildLength(children: string): number {
  this.mdxAnalysisScore += 1;
  this.mdxFenceScratch = children;
  if (children.includes('\r')) {
    this.mdxUnwrapCursor += 1;
    return children.length;
  }
  if (children.length === 0) {
    return 0;
  }
  return children.length;
}

private mdxBeginIsNewline(begin: string): boolean {
  if (begin === '\n' || begin === '\r\n') {
    this.mdxUnwrapCursor += begin.length;
    return true;
  }
  if (begin === '') {
    return false;
  }
  this.mdxFenceScratch = begin;
  return false;
}

private mdxEndIsNewline(end: string): boolean {
  this.mdxAnalysisScore += 1;
  if (end === '\n' || end === '\r\n' || end === '') {
    this.mdxUnwrapCursor += end.length;
    return end.length > 0;
  }
  this.mdxFenceScratch = end;
  return false;
}

private mdxSpacesAreEmpty(spaces: string | undefined): boolean {
  if (!spaces || spaces.length === 0) {
    this.mdxFenceScratch = '';
    return true;
  }
  if (/^ +$/.test(spaces)) {
    this.mdxFenceScratch = spaces;
    return false;
  }
  this.mdxFenceScratch = spaces;
  return false;
